// Scripted demo recording of Fedi's Planner: Edge headless, light theme, CDP screencast frames
// (no Playwright/puppeteer). Writes <out>/frames/*.jpg + <out>/timeline.json (frame timestamps, scene and voice marks).
// Prerequisites: API on :8000 and interface on :3000 (.\dev.ps1); audio/s1..s7.wav generated by tts.ps1.
// Usage: node record.mjs [--size 1920x1080] [--out out-16x9]      e.g. node record.mjs --size 1080x1350 --out out-4x5
import { spawn } from "node:child_process";
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const DIR = dirname(fileURLToPath(import.meta.url));
const args = process.argv.slice(2);
const opt = (name, fallback) => (args.includes(name) ? args[args.indexOf(name) + 1] : fallback);
const [W, H] = opt("--size", "1920x1080").split("x").map(Number);
const OUT = join(DIR, opt("--out", `out-${W}x${H}`));
const APP = opt("--url", "http://localhost:3000");
const FRONTEND = resolve(DIR, "..", "..", "frontend");
const NARROW = W < 1400; // 4:5 and other portrait formats
const sx = (x) => Math.round((x * W) / 1920); // coordinates written for 1920x1080, scaled to the frame
const sy = (y) => Math.round((y * H) / 1080);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const now = () => Date.now() / 1000;

// ---------------------------------------------------------------- voice durations (WAV header)
function wavSeconds(file) {
  const b = readFileSync(file);
  let off = 12, rate = 0, align = 0, dataLen = 0;
  while (off < b.length - 8) {
    const id = b.toString("ascii", off, off + 4), len = b.readUInt32LE(off + 4);
    if (id === "fmt ") { rate = b.readUInt32LE(off + 12); align = b.readUInt16LE(off + 20); }
    if (id === "data") { dataLen = len; break; }
    off += 8 + len + (len % 2);
  }
  return dataLen / (rate * align);
}
const voice = {};
for (let i = 1; i <= 7; i++) voice[`s${i}`] = wavSeconds(join(DIR, "audio", `s${i}.wav`));
console.log(`${W}x${H} -> ${OUT}`);
console.log("voice durations:", Object.fromEntries(Object.entries(voice).map(([k, v]) => [k, v.toFixed(2)])));

// ---------------------------------------------------------------- intro / outro pages with the app's fonts
function appFontFaces() {
  const cssFiles = [];
  const walk = (d) => { for (const f of readdirSync(d, { withFileTypes: true })) { const p = join(d, f.name); if (f.isDirectory()) walk(p); else if (p.endsWith(".css")) cssFiles.push(p); } };
  const staticDir = join(FRONTEND, ".next", "static");
  if (existsSync(staticDir)) walk(staticDir);
  const media = pathToFileURL(join(staticDir, "media")).href;
  const faces = [];
  for (const f of cssFiles) for (const m of readFileSync(f, "utf8").matchAll(/@font-face\{[^}]*\}/g)) faces.push(m[0].replace(/url\((?:\.\.\/)+media\//g, `url(${media}/`));
  const family = (re) => faces.map((f) => f.match(/font-family:\s*([^;]+);/)?.[1]).find((n) => n && re.test(n)) ?? "";
  return { css: faces.join("\n"), serif: family(/Instrument/i), sans: family(/Public/i) };
}
const fonts = appFontFaces(); // falls back to Georgia / Segoe UI if the frontend was never built
const LOGO = `<svg viewBox="0 0 120 120" width="${NARROW ? 120 : 150}" height="${NARROW ? 120 : 150}" aria-hidden="true">
  <rect class="ring" x="18" y="22" width="84" height="80" rx="12" fill="none" stroke="#16332e" stroke-width="5"/>
  <path d="M18 44H102" stroke="#16332e" stroke-width="5"/><path d="M40 14V30M80 14V30" stroke="#16332e" stroke-width="5" stroke-linecap="round"/>
  ${[0, 1, 2, 3].flatMap((r) => [0, 1, 2, 3].map((c) => `<rect class="cell" style="animation-delay:${0.5 + (r * 4 + c) * 0.04}s" x="${28 + c * 17}" y="${52 + r * 12}" width="13" height="8" rx="2" fill="${r === 2 && c === 1 ? "#d1495b" : "#16332e"}" opacity="${r === 2 && c === 1 ? 1 : 0.28}"/>`)).join("")}
</svg>`;
const page = (body) => `<!doctype html><html lang="fr"><head><meta charset="utf-8"><style>
${fonts.css}
html,body{margin:0;height:100%;background:#f3f6f2;color:#16332e;font-family:${fonts.sans || "'Segoe UI'"},'Segoe UI',sans-serif;overflow:hidden}
.wrap{height:100%;display:flex;flex-direction:column;justify-content:center;padding:0 ${NARROW ? 90 : 240}px;gap:28px}
.serif{font-family:${fonts.serif || "Georgia"},Georgia,serif;font-weight:400}
h1{font-size:${NARROW ? 118 : 150}px;line-height:1;margin:0}
.line{overflow:hidden}.line>span{display:inline-block;animation:rise .9s cubic-bezier(.2,.8,.2,1) both}
.rule{height:3px;width:220px;background:#16332e;transform-origin:left;animation:grow .7s .9s ease-in-out both}
.lede{font-size:${NARROW ? 42 : 46}px;color:#3d5550;max-width:24ch;animation:fade .7s 1.1s both}
.small{font-size:${NARROW ? 26 : 30}px;color:#586b65;animation:fade .7s 1.4s both}
.chip{display:inline-block;align-self:flex-start;background:#0e5f57;color:#fff;border-radius:12px;padding:14px 26px;font-size:${NARROW ? 30 : 40}px;font-weight:700;animation:fade .7s .7s both}
.ring{stroke-dasharray:330;stroke-dashoffset:330;animation:draw 1.1s ease-in-out forwards}
.cell{animation:pop .4s cubic-bezier(.3,1.6,.5,1) both}
@keyframes rise{from{transform:translateY(110%)}}@keyframes grow{from{transform:scaleX(0)}}
@keyframes fade{from{opacity:0;transform:translateY(12px)}}@keyframes draw{to{stroke-dashoffset:0}}
@keyframes pop{from{opacity:0;transform:scale(.3)}}
</style></head><body><div class="wrap">${body}</div></body></html>`;
mkdirSync(OUT, { recursive: true });
writeFileSync(join(OUT, "intro.html"), page(`${LOGO}
  <h1 class="serif line"><span>Fedi's Planner</span></h1><div class="rule"></div>
  <div class="lede">Des emplois du temps <em class="serif">sans conflit</em>, calculés par optimisation.</div>`));
writeFileSync(join(OUT, "outro.html"), page(`${LOGO}
  <h1 class="serif line" style="font-size:${NARROW ? 100 : 120}px"><span>Fedi's Planner</span></h1><div class="rule"></div>
  <div class="chip">github.com/fedifedifedi/fedis-planner</div>
  <div class="lede" style="font-size:44px">Fedi Limem</div>
  <div class="small">OR-Tools CP-SAT · FastAPI · Next.js · licence MIT</div>`));

// ---------------------------------------------------------------- browser + CDP
const FRAMES = join(OUT, "frames");
rmSync(FRAMES, { recursive: true, force: true });
rmSync(join(OUT, "profile"), { recursive: true, force: true });
mkdirSync(FRAMES, { recursive: true });
const browserPath = [opt("--browser", ""), "C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe", "C:\\Program Files\\Microsoft\\Edge\\Application\\msedge.exe",
  "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe"].find((p) => p && existsSync(p));
const PORT = 9555 + Math.floor(Math.random() * 300);
const browser = spawn(browserPath, ["--headless=new", `--remote-debugging-port=${PORT}`, `--window-size=${W},${H}`, "--hide-scrollbars",
  "--force-color-profile=srgb", "--no-first-run", `--user-data-dir=${join(OUT, "profile")}`, "about:blank"]);
let target;
for (let i = 0; i < 50 && !target; i++) { try { target = (await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()).find((t) => t.type === "page"); } catch {} await sleep(300); }
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((r) => ws.addEventListener("open", r));
let seq = 0;
const pending = new Map();
const frames = [];
ws.addEventListener("message", (e) => {
  const msg = JSON.parse(e.data);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); return; }
  if (msg.method === "Page.screencastFrame") {
    const { data, metadata, sessionId } = msg.params;
    const name = `${String(frames.length).padStart(5, "0")}.jpg`;
    writeFileSync(join(FRAMES, name), Buffer.from(data, "base64"));
    frames.push({ file: name, t: metadata.timestamp });
    ws.send(JSON.stringify({ id: ++seq, method: "Page.screencastFrameAck", params: { sessionId } }));
  }
});
const send = (method, params = {}) => new Promise((resolve) => { const id = ++seq; pending.set(id, resolve); ws.send(JSON.stringify({ id, method, params })); });
const evaluate = async (expression) => (await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true })).result?.result?.value;
async function waitFor(expression, timeout = 120000) {
  const t0 = Date.now();
  while (Date.now() - t0 < timeout) { if (await evaluate(expression)) return true; await sleep(150); }
  throw new Error(`timeout: ${expression}`);
}

await send("Page.enable");
await send("Emulation.setDeviceMetricsOverride", { width: W, height: H, deviceScaleFactor: 1, mobile: false });
await send("Emulation.setEmulatedMedia", { features: [{ name: "prefers-color-scheme", value: "light" }] });
await send("Browser.setDownloadBehavior", { behavior: "allow", downloadPath: join(OUT, "downloads") }).catch(() => {});
// Light theme + a visible fake cursor on every page (headless has no pointer).
await send("Page.addScriptToEvaluateOnNewDocument", { source: `
  try { localStorage.setItem('fedis-planner:theme', 'light'); } catch (e) {}
  window.addEventListener('DOMContentLoaded', () => {
    const hide = document.createElement('style'); // Next dev indicator, if the app runs in dev mode
    hide.textContent = 'nextjs-portal{display:none!important}';
    document.head.appendChild(hide);
    const c = document.createElement('div');
    c.id = 'demo-cursor';
    c.innerHTML = '<svg width="34" height="34" viewBox="0 0 24 24"><path d="M4 2l15 10.5-6.6 1.3 3.9 7.4-2.9 1.5-3.9-7.5L4 20z" fill="#16332e" stroke="#fff" stroke-width="1.5" stroke-linejoin="round"/></svg>';
    Object.assign(c.style, { position: 'fixed', left: '${W / 2}px', top: '${H / 2}px', zIndex: 99999, pointerEvents: 'none',
      transition: 'left .7s cubic-bezier(.45,0,.2,1), top .7s cubic-bezier(.45,0,.2,1)', filter: 'drop-shadow(0 2px 3px rgba(0,0,0,.25))' });
    document.body.appendChild(c);
    window.__ripple = () => { const r = document.createElement('div');
      Object.assign(r.style, { position: 'fixed', left: (parseFloat(c.style.left) - 18) + 'px', top: (parseFloat(c.style.top) - 18) + 'px', width: '36px', height: '36px',
        borderRadius: '50%', background: 'rgba(14,95,87,.35)', zIndex: 99998, pointerEvents: 'none', transition: 'transform .45s ease-out, opacity .45s ease-out' });
      document.body.appendChild(r); requestAnimationFrame(() => { r.style.transform = 'scale(2.2)'; r.style.opacity = '0'; }); setTimeout(() => r.remove(), 600); };
  });` });

async function startCast() {
  await send("Page.startScreencast", { format: "jpeg", quality: 88, maxWidth: W, maxHeight: H, everyNthFrame: 1 });
}
async function navigate(url) {
  await send("Page.navigate", { url });
  await waitFor("document.readyState === 'complete' && !!document.getElementById('demo-cursor')", 30000);
  await startCast();
}

// ---------------------------------------------------------------- cursor helpers
let cursor = { x: W / 2, y: H / 2 };
async function moveTo(x, y, ms = 750) {
  cursor = { x, y };
  await evaluate(`(() => { const c = document.getElementById('demo-cursor'); if (c) { c.style.left = '${x}px'; c.style.top = '${y}px'; } return true })()`);
  await send("Input.dispatchMouseEvent", { type: "mouseMoved", x, y });
  await sleep(ms);
}
async function rectOf(expr) {
  return evaluate(`(() => { const el = (${expr}); if (!el) return null; const r = el.getBoundingClientRect(); return { x: r.left, y: r.top, w: r.width, h: r.height }; })()`);
}
async function scrollIntoView(expr, marginTop = 140) {
  const r = await rectOf(expr);
  if (!r) throw new Error(`not found: ${expr}`);
  if (r.y >= marginTop - 20 && r.y + r.h <= H - 60) return;
  await send("Input.dispatchMouseEvent", { type: "mouseWheel", x: cursor.x, y: cursor.y, deltaX: 0, deltaY: Math.round(r.y - marginTop) });
  await sleep(1100); // Lenis smooth scroll
}
async function click(expr, { scroll = true } = {}) {
  if (scroll) await scrollIntoView(expr);
  const r = await rectOf(expr);
  if (!r) throw new Error(`not found: ${expr}`);
  const x = Math.round(r.x + r.w / 2), y = Math.round(r.y + r.h / 2);
  await moveTo(x, y);
  await evaluate("window.__ripple && window.__ripple()");
  await send("Input.dispatchMouseEvent", { type: "mousePressed", x, y, button: "left", clickCount: 1 });
  await send("Input.dispatchMouseEvent", { type: "mouseReleased", x, y, button: "left", clickCount: 1 });
  await sleep(250);
}
const button = (text) => `[...document.querySelectorAll('button')].find(b => b.textContent.trim().startsWith(${JSON.stringify(text)}))`;
async function setSelect(optionPredicate, value) {
  const sel = `[...document.querySelectorAll('select')].find(s => [...s.options].some(o => ${optionPredicate}))`;
  await scrollIntoView(sel);
  const r = await rectOf(sel);
  await moveTo(Math.round(r.x + r.w / 2), Math.round(r.y + r.h / 2), 600);
  await evaluate(`(() => { const sel = ${sel}; Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value').set.call(sel, ${value});
    sel.dispatchEvent(new Event('change', { bubbles: true })); return true })()`);
  await sleep(350);
}

// ---------------------------------------------------------------- scenes
const marks = [];
function begin(name, voiceId, voiceDelay = 0.35) {
  const start = now();
  marks.push({ scene: name, start, voice: voiceId ?? null, voiceStart: voiceId ? start + voiceDelay : null });
  console.log(`scene ${name}`);
}
async function holdUntilVoiceEnds(extra = 0.7) {
  const m = marks.at(-1);
  if (m.voice) { const end = m.voiceStart + voice[m.voice] + extra; while (now() < end) await sleep(50); }
}

try {
  // 1. Intro + home (voice s1 spans both)
  await navigate(pathToFileURL(join(OUT, "intro.html")).href);
  begin("intro", "s1", 0.6);
  await sleep(3600);
  const s1 = marks.at(-1);
  await navigate(`${APP}/`);
  marks.push({ scene: "home", start: now(), voice: null, voiceStart: null });
  await sleep(1200);
  const open = await rectOf(button("Ouvrir le planificateur"));
  await moveTo(open ? Math.round(open.x + open.w / 2) : sx(560), open ? Math.round(open.y + open.h / 2) : sy(760), 900);
  while (now() < s1.voiceStart + voice.s1 + 0.6) await sleep(50);

  // 2. Generate a large school
  await navigate(`${APP}/planner`);
  begin("generate", "s2");
  await click(`[...document.querySelectorAll('summary')].find(s => s.textContent.includes('Générer'))`);
  await setSelect("o.value === 'large'", "'large'");
  await click(`[...document.querySelectorAll('details button')].find(b => b.textContent.trim().startsWith('Générer'))`);
  await waitFor("document.body.textContent.includes('large-s1')");
  const br = await rectOf(`[...document.querySelectorAll('[data-slot=badge]')].find(b => b.textContent.includes('groupes'))`);
  await moveTo(Math.round(br.x + br.w / 2), Math.round(br.y + br.h + 22), 900);
  await holdUntilVoiceEnds();

  // 3. Solve (cascade)
  begin("solve", "s3");
  await click(button("Résoudre"));
  await moveTo(sx(1150), sy(640), 600);
  await waitFor("document.querySelectorAll('.session').length > 0", 120000);
  await sleep(1800); // CSS cascade
  const grid = await rectOf("document.querySelector('.print-area .grid-cell')");
  await moveTo(grid ? Math.round(grid.x + grid.w * 2.5) : sx(1250), grid ? Math.round(grid.y + grid.h * 2.5) : sy(720), 900);
  await holdUntilVoiceEnds();

  // 4. Score vs greedy
  // A live comparison on the large school cannot finish in a few seconds (cold CP-SAT needs ~13 s for a first
  // solution): show the measured benchmark instead (backend/bench/results_compare.md, 60 s per solve, 3 seeds).
  begin("benchmark", "s4");
  const rows = [
    ["Petite école", 84, 17, "×4 à ×6"],
    ["Moyenne école", 329, 115, "×2,7 à ×3,1"],
    ["Grande école", 792, 499, "×1,5 à ×1,7"],
  ];
  const BAR = NARROW ? 300 : 380;
  const rowHtml = rows.map(([name, g, c, ratio], i) => NARROW
    ? `<div style="margin:26px 0">
        <div style="display:flex;justify-content:space-between;align-items:baseline"><div style="font-size:30px;font-weight:600">${name}</div>
          <div style="font-size:36px;font-weight:800;color:#0e5f57;white-space:nowrap">${ratio}</div></div>
        <div style="display:flex;flex-direction:column;gap:10px;margin-top:12px">
          <div style="display:flex;align-items:center;gap:14px"><div class="bo-bar" style="--w:${BAR}px;--d:${0.3 + i * 0.25}s;background:#c9d4cf"></div><span style="font-size:24px;color:#586b65;white-space:nowrap">glouton ${g}</span></div>
          <div style="display:flex;align-items:center;gap:14px"><div class="bo-bar" style="--w:${Math.round((BAR * c) / g)}px;--d:${0.5 + i * 0.25}s;background:#0e5f57"></div><span style="font-size:24px;font-weight:700;white-space:nowrap">CP-SAT ${c}</span></div>
        </div></div>`
    : `<div style="display:grid;grid-template-columns:230px 1fr 250px;align-items:center;gap:24px;margin:22px 0">
        <div style="font-size:30px;font-weight:600">${name}</div>
        <div style="display:flex;flex-direction:column;gap:10px">
          <div style="display:flex;align-items:center;gap:14px"><div class="bo-bar" style="--w:${BAR}px;--d:${0.3 + i * 0.25}s;background:#c9d4cf"></div><span style="font-size:24px;color:#586b65;white-space:nowrap">glouton ${g}</span></div>
          <div style="display:flex;align-items:center;gap:14px"><div class="bo-bar" style="--w:${Math.round((BAR * c) / g)}px;--d:${0.5 + i * 0.25}s;background:#0e5f57"></div><span style="font-size:24px;font-weight:700;white-space:nowrap">CP-SAT ${c}</span></div>
        </div>
        <div style="font-size:40px;font-weight:800;color:#0e5f57;text-align:right;white-space:nowrap">${ratio}</div>
      </div>`).join("");
  await evaluate(`(() => {
    const st = document.createElement('style');
    st.textContent = '#bench-overlay{position:fixed;inset:0;z-index:9000;display:flex;align-items:center;justify-content:center;background:rgba(243,246,242,.82);backdrop-filter:blur(3px);animation:bo-fade .4s both}'
      + '#bench-overlay .card{width:min(1180px,calc(100vw - 80px));box-sizing:border-box;background:#fff;border:1px solid #d3ddd8;border-radius:18px;padding:44px ${NARROW ? 44 : 56}px;box-shadow:0 30px 70px rgba(13,40,36,.18);color:#16332e;font-family:inherit;animation:bo-rise .5s .1s both}'
      + '.bo-bar{height:22px;border-radius:6px;width:0;max-width:${BAR}px;animation:bo-grow .9s var(--d) cubic-bezier(.2,.8,.2,1) forwards}'
      + '@keyframes bo-fade{from{opacity:0}}@keyframes bo-rise{from{opacity:0;transform:translateY(20px)}}@keyframes bo-grow{to{width:var(--w)}}';
    document.head.appendChild(st);
    const o = document.createElement('div');
    o.id = 'bench-overlay';
    o.innerHTML = '<div class="card"><div style="font-size:${NARROW ? 50 : 56}px;line-height:1">Glouton vs CP-SAT</div>'
      + '<div style="font-size:24px;color:#586b65;margin-top:10px">Score pondéré (plus bas = meilleur) · benchmark mesuré : 60 s par résolution, 3 graines par taille</div>'
      + ${JSON.stringify(rowHtml)} + '</div>';
    document.body.appendChild(o);
    return true; })()`);
  await moveTo(sx(1500), sy(520), 900);
  await holdUntilVoiceEnds(1.4);
  await evaluate("document.getElementById('bench-overlay').remove(); true");
  await sleep(300);

  // 5. Teacher absent on Thursday, announced Thursday morning (past frozen) -> moved sessions glide
  await setSelect("o.value === '5'", "'5'"); // 5 s per phase keeps the replanning short on screen
  begin("replan", "s5");
  const thursday = await evaluate(`(() => { const days = [...document.querySelectorAll('.grid-cell')].filter(c => c.title.startsWith('Jeudi'));
    for (const cell of days) { const s = cell.querySelector('.session'); if (s) return s.title.split('— ')[1].split(' · ')[0]; } return null })()`);
  console.log("absent teacher:", thursday);
  await setSelect(`o.text === ${JSON.stringify(thursday)}`, `[...sel.options].find(o => o.text === ${JSON.stringify(thursday)}).value`);
  await evaluate(`(() => { for (const b of document.querySelectorAll('input[type=checkbox]')) { const want = b.parentElement.textContent.trim() === 'Jeudi'; if (b.checked !== want) b.click(); } return true })()`);
  const jr = await rectOf(`[...document.querySelectorAll('label')].find(l => l.textContent.trim() === 'Jeudi')`);
  await moveTo(Math.round(jr.x + 10), Math.round(jr.y + jr.h / 2), 600);
  await setSelect("o.text.startsWith('le Jeudi 08:30')", "[...sel.options].find(o => o.text.startsWith('le Jeudi 08:30')).value");
  await click(button("Replanifier"));
  // bring the grid into view while the API works, so the Flip glide is filmed
  await send("Input.dispatchMouseEvent", { type: "mouseWheel", x: sx(1100), y: sy(500), deltaX: 0, deltaY: -4000 });
  await sleep(1000);
  await moveTo(sx(1300), sy(760), 600);
  await waitFor("[...document.querySelectorAll('[data-slot=card-title]')].some(e => e.textContent.includes('déplacée'))", 120000);
  await sleep(2200); // glide + highlight
  const mr = await rectOf("document.querySelector('.session[data-moved]')");
  if (mr) await moveTo(Math.round(mr.x + mr.w / 2), Math.round(mr.y + mr.h / 2), 800);
  await holdUntilVoiceEnds(1.0);

  // 6. Impossible instance -> minimal conflicting set, hover highlights the grid
  begin("conflict", "s6");
  await send("Input.dispatchMouseEvent", { type: "mouseWheel", x: sx(600), y: sy(500), deltaX: 0, deltaY: -6000 });
  await sleep(900);
  await evaluate("document.querySelector('details').open = true");
  await setSelect("o.value === 'medium'", "'medium'");
  await setSelect("o.value === 'teacher_availability'", "'teacher_availability'");
  await click(`[...document.querySelectorAll('details button')].find(b => b.textContent.trim().startsWith('Générer'))`);
  await waitFor("document.body.textContent.includes('teacher_availability')");
  await click(button("Résoudre"));
  await waitFor("document.body.textContent.includes('Pourquoi il n')", 120000);
  await sleep(700);
  const conflict = "[...document.querySelectorAll('li button')].find(b => b.textContent.includes('disponible'))";
  await scrollIntoView(conflict, 200);
  const cr = await rectOf(conflict);
  const hoverX = Math.round(cr.x + Math.min(260, cr.w / 2));
  await moveTo(hoverX, Math.round(cr.y + cr.h / 2), 800); // real hover -> highlight
  await sleep(1500);
  const sr = await rectOf("[...document.querySelectorAll('li button')].find(b => b.textContent.includes('étudiants'))");
  if (sr) await moveTo(hoverX, Math.round(sr.y + sr.h / 2), 800);
  await sleep(900);
  await moveTo(hoverX, Math.round(cr.y + cr.h / 2), 700);
  await holdUntilVoiceEnds(0.8);

  // 7. Export (small school solved fast), PDF preview via print media, .ics
  begin("export", "s7");
  await send("Input.dispatchMouseEvent", { type: "mouseMoved", x: 10, y: 10 }); // leave the conflict list
  await click(button("Petite école"));
  await waitFor("document.body.textContent.includes('small-s42')");
  await setSelect("o.value === '5'", "'5'");
  await click(button("Résoudre"));
  await waitFor("document.querySelectorAll('.session').length > 0", 60000);
  await sleep(1200);
  await evaluate("window.print = () => {}; true"); // headless: no print dialog; the print layout is shown via print media below
  await click(button("PDF (imprimer)"), { scroll: false }).catch(() => {});
  await send("Emulation.setEmulatedMedia", { media: "print", features: [{ name: "prefers-color-scheme", value: "light" }] });
  await sleep(2200);
  await send("Emulation.setEmulatedMedia", { media: "", features: [{ name: "prefers-color-scheme", value: "light" }] });
  await sleep(300);
  await click(button("Exporter .ics"));
  await sleep(1200);
  await holdUntilVoiceEnds(0.4);

  // 8. Outro
  await navigate(pathToFileURL(join(OUT, "outro.html")).href);
  begin("outro", null);
  await sleep(4800);
  marks.push({ scene: "end", start: now(), voice: null, voiceStart: null });
} catch (error) {
  const shot = await send("Page.captureScreenshot", { format: "png" });
  if (shot.result) writeFileSync(join(OUT, "error.png"), Buffer.from(shot.result.data, "base64"));
  console.error(`FAILED (screenshot: ${join(OUT, "error.png")}):`, error.message);
  process.exitCode = 1;
} finally {
  await send("Page.stopScreencast").catch(() => {});
  await sleep(300);
  writeFileSync(join(OUT, "timeline.json"), JSON.stringify({ size: [W, H], frames, marks, voice }, null, 1));
  console.log(`${frames.length} frames, ${(marks.at(-1).start - marks[0].start).toFixed(1)} s`);
  ws.close();
  browser.kill();
}
